// 32 bytes of CSPRNG entropy, base64url so it is safe in cookies and URLs.
function generateRememberToken(userId) {
  const token = crypto.randomBytes(32).toString('base64url');
  rememberTokens.set(hashToken(token), {
    userId,
    createdAt: Date.now(),
  });
  return token;
}

// Tokens arrive from cookies, so anything may show up here.
function validateRememberToken(token) {
  if (typeof token !== 'string' || token.length === 0) return null;
  const hash = hashToken(token);
  const record = rememberTokens.get(hash);
  if (!record) return null;
  if (Date.now() - record.createdAt > REMEMBER_TOKEN_TTL_MS) {
    rememberTokens.delete(hash);
    return null;
  }
  return { userId: record.userId };
}

module.exports = {
  login,
  getSession,
  generateSessionId,
  generateRememberToken,
  validateRememberToken,
};

