test('remember token is url-safe and validates back to the user', () => {
  const token = generateRememberToken('u1');
  assert.match(token, /^[A-Za-z0-9_-]+$/);
  assert.strictEqual(encodeURIComponent(token), token);
  assert.deepStrictEqual(validateRememberToken(token), { userId: 'u1' });
});

test('remember tokens are unique and carry enough entropy', () => {
  const tokens = new Set();
  for (let i = 0; i < 100; i++) {
    const token = generateRememberToken('u1');
    // 32 raw bytes -> 43 base64url chars
    assert.ok(token.length >= 43, `token too short: ${token.length}`);
    tokens.add(token);
  }
  assert.strictEqual(tokens.size, 100);
});

test('unknown, empty and non-string tokens are rejected', () => {
  assert.strictEqual(validateRememberToken('not-a-real-token'), null);
  assert.strictEqual(validateRememberToken(''), null);
  assert.strictEqual(validateRememberToken(undefined), null);
  assert.strictEqual(validateRememberToken(null), null);
  assert.strictEqual(validateRememberToken(42), null);
  assert.strictEqual(validateRememberToken({}), null);
});

test('a tampered token does not validate', () => {
  const token = generateRememberToken('u1');
  const tampered = token.slice(0, -1) + (token.endsWith('A') ? 'B' : 'A');
  assert.strictEqual(validateRememberToken(tampered), null);
});

test('tokens for different users stay separate', () => {
  const a = generateRememberToken('u1');
  const b = generateRememberToken('u2');
  assert.strictEqual(validateRememberToken(a).userId, 'u1');
  assert.strictEqual(validateRememberToken(b).userId, 'u2');
});

test('an expired remember token is rejected', () => {
  const token = generateRememberToken('u1');
  const realNow = Date.now;
  Date.now = () => realNow() + 31 * 24 * 60 * 60 * 1000;
  try {
    assert.strictEqual(validateRememberToken(token), null);
  } finally {
    Date.now = realNow;
  }
  // still rejected once the clock is back to normal: the record is gone
  assert.strictEqual(validateRememberToken(token), null);
});

